-- Productos pendientes de cargar (188), cruzados contra la base el 2026-10-14.
-- Entran con stock_total = 0: el stock real se carga como lotes en lotes_inventario.
-- ON CONFLICT DO NOTHING: si un producto ya existe (id, sku o codigo_barra), se omite sin error.
BEGIN;

ON CONFLICT DO NOTHING;

-- stock_total = suma de los lotes activos de cada producto (misma regla que el trigger trg_recalcular_stock).
-- Corrige los productos ya cargados que tenían stock sin lotes que lo respalden.
UPDATE productos p
SET stock_total = COALESCE((
  SELECT SUM(l.cantidad) FROM lotes_inventario l
  WHERE l.producto_id = p.id AND l.activo
), 0)
WHERE p.stock_total IS DISTINCT FROM COALESCE((
  SELECT SUM(l.cantidad) FROM lotes_inventario l
  WHERE l.producto_id = p.id AND l.activo
), 0);

COMMIT;

-- Verificación: 390 productos y ninguno con stock sin lotes
SELECT count(*) AS total_productos,
       count(*) FILTER (WHERE stock_total > 0) AS con_stock
FROM productos;
